with lines as (select id, plan, effective_from, currency, val from price_tiers lateral view explode(discounts) t as val), enriched as (select *, sum(val) over (partition by plan) plan_sum_val from lines), base as (select id, val, plan_sum_val, val - plan_sum_val val_minus_plan_sum_val, val - plan_sum_val val_minus_plan_sum_val_2 from enriched where effective_from >= date '2024-03-13' and plan_sum_val <= 320), with_windows as (select val_minus_plan_sum_val, val_minus_plan_sum_val_2, dense_rank() over (order by val desc nulls first) val_dense_rank, rank() over (order by val) val_rank from base), filtered as (select *, coalesce(val_dense_rank, 0) val_dense_rank_filled, val_rank + val_dense_rank val_rank_plus_val_dense_rank from with_windows where val_minus_plan_sum_val_2 is not null) select val_minus_plan_sum_val, val_minus_plan_sum_val_2, val_dense_rank, val_rank, val_dense_rank_filled from filtered order by val_dense_rank_filled desc nulls last;
